/**
 * Normalize a local absolute path.
 *
 * Supports:
 * - Windows: C:\Users\lotfi\...
 * - Windows normalized: C:/Users/lotfi/...
 * - Linux: /home/concept/...
 *
 * Returns null for:
 * - relative paths
 * - invalid traversal outside the root
 */
const normalizeAbsoluteLocalPath = (value) => {
  const raw = String(value || '').trim();

  if (!raw) {
    return null;
  }

  // Normalize Windows separators to forward slashes.
  const unified = raw
    .replace(/\\/g, '/')
    .replace(/\/+/g, '/');

  const windowsDriveMatch = unified.match(/^([A-Za-z]:)(?:\/|$)/);
  const isLinuxAbsolute = unified.startsWith('/');

  if (!windowsDriveMatch && !isLinuxAbsolute) {
    return null;
  }

  let prefix;
  let remainder;

  if (windowsDriveMatch) {
    prefix = windowsDriveMatch[1].toUpperCase();
    remainder = unified.slice(prefix.length);
  } else {
    prefix = '/';
    remainder = unified.slice(1);
  }

  const segments = [];

  for (const segment of remainder.split('/')) {
    if (!segment || segment === '.') {
      continue;
    }

    if (segment === '..') {
      if (segments.length === 0) {
        return null;
      }

      segments.pop();
      continue;
    }

    segments.push(segment);
  }

  if (prefix === '/') {
    return `/${segments.join('/')}`;
  }

  return `${prefix}/${segments.join('/')}`;
};

const sharedRoot = normalizeAbsoluteLocalPath(sharedRootRaw);

if (!sharedRoot) {
  return rejectLaunch(
    'N8N_SHARED_STORAGE_ROOT doit etre un chemin absolu local valide.',
    'WORKFLOW_CONFIGURATION_ERROR',
    500
  );
}

const pdfPath = normalizeAbsoluteLocalPath(
  String(item.json.pdf_path || '').trim()
);

if (!pdfPath) {
  return rejectLaunch(
    'pdf_path doit etre un chemin absolu local valide.',
    'INVALID_PDF_PATH'
  );
}

/**
 * Security check:
 * the PDF must be inside the configured shared storage root.
 */
if (
  !(
    pdfPath === sharedRoot ||
    pdfPath.startsWith(`${sharedRoot}/`)
  )
) {
  return rejectLaunch(
    `pdf_path hors du stockage partage autorise: ${pdfPath}`,
    'INVALID_PDF_PATH'
  );
}

if (!pdfPath.toLowerCase().endsWith('.pdf')) {
  return rejectLaunch(
    `pdf_path doit cibler un fichier .pdf: ${pdfPath}`,
    'INVALID_PDF_PATH'
  );
}

const receivedAt = new Date().toISOString();

