const item = $input.first();
const rawMessage = item.json?.error || item.json?.message || 'Lecture du PDF source impossible.';
const errorMessage = typeof rawMessage === 'string' ? rawMessage : JSON.stringify(rawMessage);

return [{
  json: {
    error_stage: 'UPLOAD',
    error_code: 'SOURCE_PDF_READ_FAILED',
    error_message: errorMessage,
  },
}];

const item = $input.first();
const binaryField = 'data';
const buffer = await this.helpers.getBinaryDataBuffer(0, binaryField);
const header = buffer.subarray(0, 4).toString('utf8');
const pdfSizeBytes = Number(item.binary?.[binaryField]?.fileSize || buffer.length || 0);

if (header !== '%PDF') {
  return [{
    json: {
      source_pdf_valid: false,
      error_stage: 'UPLOAD',
      error_code: 'INVALID_PDF_FILE',
      error_message: `Le fichier n\'a pas une signature PDF valide: ${item.binary?.[binaryField]?.fileName || 'source.pdf'}`,
      pdf_size_bytes: pdfSizeBytes,
    },
    binary: item.binary,
  }];
}

return [{
  json: {
    source_pdf_valid: true,
    marker_binary_field: binaryField,
    pdf_size_bytes: pdfSizeBytes,
  },
  binary: item.binary,
}];

const item = $input.first();
const now = Date.now();

return [{
  json: {
    ...item.json,
    marker_poll_count: 0,
    marker_started_at: now,
    marker_max_polls: 40,
    marker_max_elapsed_ms: 1200000,
  },
  binary: item.binary,
}];

const item = $input.first();
const now = Date.now();
const pollCount = Number(item.json.marker_poll_count ?? 0) + 1;
const startedAt = Number(item.json.marker_started_at ?? now);
const maxPolls = Number(item.json.marker_max_polls ?? 10);
const maxElapsedMs = Number(item.json.marker_max_elapsed_ms ?? 300000);
const elapsedMs = now - startedAt;
const timedOut = pollCount >= maxPolls || elapsedMs >= maxElapsedMs;

return [{
  json: {
    ...item.json,
    marker_timed_out: timedOut,
    marker_poll_count: pollCount,
    marker_started_at: startedAt,
    marker_max_polls: maxPolls,
    marker_max_elapsed_ms: maxElapsedMs,
    marker_elapsed_ms: elapsedMs,
    marker_last_poll_at: now,
  },
  binary: item.binary,
}];

const item = $input.first();
let text;

if (item.binary && Object.keys(item.binary).length > 0) {
  const binaryKey = Object.keys(item.binary)[0];
  const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
  text = buffer.toString('utf-8');
} else {
  text = item.json.markdown;
}

return [{
  json: {
    ...item.json,
    text,
    markdown: text,
  },
}];

